#include <vector>
#include <set>
#include <algorithm>

void unique_set(const std::vector<int>& data) {
    // O(N log N) total due to N insertions
    std::set<int> s(data.begin(), data.end());
}

void unique_vector(std::vector<int>& data) {
    // O(N log N) dominated by sort
    std::sort(data.begin(), data.end());
    // O(N) to remove adjacent duplicates
    data.erase(std::unique(data.begin(), data.end()), data.end());
}
